// ============================================================
// FILTRO KEYWORDS & ELEGIBILIDAD - Versión Robusta v3 (Sin Marcadores)
// ============================================================
const elegiblesSQL = $input.all(); 
let regla = {};
let negocio = {};

try {
    regla = $("Loop Reglas").last().json;
} catch (e) {
    try { regla = $nodes["Loop Reglas"].json; } catch (e2) { regla = {}; }
}

try {
    negocio = $("Obtener Negocios Activos").first().json;
} catch (e) {
    try { negocio = $nodes["Obtener Negocios Activos"].json; } catch (e2) { negocio = {}; }
}

let marcaIdentidad = negocio.marca_identidad || {};
if (typeof marcaIdentidad === 'string') {
    try { marcaIdentidad = JSON.parse(marcaIdentidad); } catch(e) {}
}

const adn = marcaIdentidad.adn_json || {};
const vocabulario = adn.vocabulario || { nunca_usar: [], usar_siempre: [] };
const trato = adn.trato || { mujer: 'reina' };
const emojis = adn.emojis || { firma: '✨' };

const elegiblesFinal = [];

for (const item of elegiblesSQL) {
    const cliente = item.json; 

    if (!cliente || cliente.sin_clientes === true || !cliente.cliente_id || !cliente.telefono) {
        continue; 
    }

    const citaIdNum = Number(cliente.cita_id);
    if (!cliente.cita_id || isNaN(citaIdNum) || citaIdNum <= 0) continue;

    const nombreFinal = cliente.cliente_nombre || trato.mujer || 'reina';
    const businessId = regla.business_id || negocio.id || null;

    if (!businessId || businessId === 'undefined' || businessId === 'null') continue;

    elegiblesFinal.push({
        json: {
            cita_id: citaIdNum, 
            business_id: businessId,
            cliente_id: cliente.cliente_id,
            telefono: cliente.telefono,
            tipo_mensaje: "mantenimiento_servicio", 
            canal: "whatsapp",
            cliente_nombre: nombreFinal,
            servicio_realizado: cliente.servicio_realizado || regla.servicio || "servicio",
            dias_pasados: cliente.dias_pasados,
            regla_keywords: regla.keywords || "",
            bot_nombre: adn.nombre_bot || 'Luna',
            bot_personalidad: adn.personalidad || 'Asesora premium',
            tipo_negocio: adn.tipo_negocio || 'Salon Premium',
            trato_mujer: trato.mujer || 'reina',
            emojis_firma: emojis.firma || '✨💖',
            propuesta_valor: adn.propuesta_valor || 'experiencia exclusiva',
            cierre_agenda: adn.cierre_agenda || 'Que dia te viene mejor?',
            palabras_prohibidas: Array.isArray(vocabulario.nunca_usar) ? vocabulario.nunca_usar.join(', ') : "",
            palabras_obligatorias: Array.isArray(vocabulario.usar_siempre) ? vocabulario.usar_siempre.join(', ') : ""
        }
    });
}

// Retornamos la lista limpia de elegibles. Si está vacía, retornamos []
// n8n continuará al Done branch del Loop Clientes inmediatamente
return elegiblesFinal;

