// Bug #A Fix: Protección JSON.parse para respuesta de Gemini (Retoque)
const raw = $input.first().json?.content?.parts?.[0]?.text || '';

let mensaje = '';
try {
    const match = raw.match(/\{[\s\S]*?"mensaje"[\s\S]*?\}/);
    if (match) {
        const parsed = JSON.parse(match[0]);
        mensaje = parsed.mensaje || '';
    }
} catch(e) {
    console.error('❌ Error JSON parse (Retoque):', e.message, '| Raw:', raw.substring(0, 200));
}

const tieneArtifacts = mensaje.includes('undefined') || mensaje.includes('{nombre}') || mensaje.includes('null');
const ia_ok = !!(mensaje && !tieneArtifacts && mensaje.length >= 20);

if (!ia_ok) console.error('⚠️ Mensaje inválido Retoque | cliente:', $input.first().json?.cliente_id);

return [{ json: { ...$input.first().json, mensaje_limpio: mensaje, ia_ok } }];

// ============================================================
// GATEKEEPER DINAMICO v2 — Retoque / Servicios
// return [] = parada silenciosa
// ============================================================
const config = $input.item.json;

if (config.pausa_global === true) return [];
if (config.pausa_retoque === true) return [];

const sched = config.autopilot_schedules?.retoque;
if (!sched || sched.activo === false) return [];

const ahora = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Lima' }));
const diaActual = ahora.getDay();
const minutosActuales = ahora.getHours() * 60 + ahora.getMinutes();

if (!sched.dias.includes(diaActual)) return [];

const enVentana = (sched.horas || []).some(h => {
  const [hh, mm] = h.split(':').map(Number);
  return Math.abs(minutosActuales - (hh * 60 + mm)) <= 29;
});

if (!enVentana) return [];

return [{ json: config }];
